const removeParticipant = `-- name: RemoveParticipant :execrows
DELETE FROM booking_participant p
USING booking b
WHERE
    p.id = $1
    AND p.booking_id = b.id
    AND b.id = $2
    AND b.user_id = $3
`

type RemoveParticipantParams struct {
	ID        uuid.UUID     `json:"id"`
	BookingID uuid.UUID     `json:"booking_id"`
	OwnerID   uuid.NullUUID `json:"owner_id"`
}

// Only the owner of the booking removes someone.
func (q *Queries) RemoveParticipant(ctx context.Context, arg RemoveParticipantParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, removeParticipant, arg.ID, arg.BookingID, arg.OwnerID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}

const setBookingInviteToken = `-- name: SetBookingInviteToken :one
UPDATE booking
SET
    invite_token = gen_random_uuid()
WHERE
    id = $1
    AND user_id = $2
    AND status = 'confirmed'
RETURNING
    invite_token
`

type SetBookingInviteTokenParams struct {
	ID      uuid.UUID     `json:"id"`
	OwnerID uuid.NullUUID `json:"owner_id"`
}

// A new token makes the previous link stop working.
func (q *Queries) SetBookingInviteToken(ctx context.Context, arg SetBookingInviteTokenParams) (uuid.NullUUID, error) {
	row := q.db.QueryRowContext(ctx, setBookingInviteToken, arg.ID, arg.OwnerID)
	var invite_token uuid.NullUUID
	err := row.Scan(&invite_token)
	return invite_token, err
}

const setBookingPublic = `-- name: SetBookingPublic :execrows
UPDATE booking
SET
    kind       = CASE WHEN $1::BOOLEAN THEN 'public' ELSE 'private' END::booking_kind,
    public_description = COALESCE($2::TEXT, public_description),
    updated_at = NOW()
WHERE
    id = $3
    AND user_id = $4
    AND status = 'confirmed'
    AND starts_at > NOW()
`

type SetBookingPublicParams struct {
	IsPublic          bool           `json:"is_public"`
	PublicDescription sql.NullString `json:"public_description"`
	ID                uuid.UUID      `json:"id"`
	OwnerID           uuid.NullUUID  `json:"owner_id"`
}

// The owner makes an upcoming booking public or private again; capacity is checked in the API.
func (q *Queries) SetBookingPublic(ctx context.Context, arg SetBookingPublicParams) (int64, error) {
	result, err := q.db.ExecContext(ctx, setBookingPublic,
		arg.IsPublic,
		arg.PublicDescription,
		arg.ID,
		arg.OwnerID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected()
}
